window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"phy","n":"Physics","tab":"Physics","w":"Motion, heat and sound, light, electricity and magnetism.","topics":[{"id":"mechanics","n":"Motion, Force, Units and Measurement","qs":[{"id":"q1579","q":"Which instrument can be used to measure internal and the external dimensions of an object?","o":["Viscometer","Vernier Caliper","Wattmeter","Venturimeter"],"a":1,"x":"A Vernier caliper measures internal and external dimensions (and depth) accurately, to about 0.1 mm.","e":"A screw gauge (micrometer) is more precise, to about 0.01 mm.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0491","q":"A type of motion in which all parts of an object move in the same direction in a given time is called _________ motion.","o":["translation","rotational","periodic","oscillation"],"a":0,"x":"In translatory motion every part of a body moves the same distance in the same direction in the same time.","e":"A car on a straight road. A spinning fan is rotational motion.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0531","q":"Which among the following is an example of double class 1 lever?","o":["Scissors","Wheelbarrow","Broom","Nut cracker"],"a":0,"x":"Scissors are a double class-1 lever: two levers joined at a pivot (fulcrum) that sits between the effort (handles) and the load (blades).","e":"Wheelbarrow and nutcracker: class 2. Broom and tongs: class 3.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0572","q":"The attractional force applied by the earth on an object in the downward direction is called _____________.","o":["Muscular Force","Air Resistance","Frictional Force","Gravitational Force"],"a":3,"x":"The force with which Earth pulls an object downward is gravitational force; for an object, this pull is its weight (W = mg).","e":"g is about 9.8 m/s² at Earth's surface.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0730","q":"The concepts of work and energy share which one of the following units of measurement?","o":["Watt","Ohm","Joule","Ampere"],"a":2,"x":"Work and energy share the SI unit joule (J): 1 J = 1 newton × 1 metre.","e":"Power is measured in watts: 1 W = 1 J per second.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1790","q":"Which of the following is not an equation of an object moving at uniform acceleration?","o":["v = u + at","u = 1/(at2)","2as = v2 – u2","s = ut + 1/(2at2)"],"a":1,"x":"The three equations of uniformly accelerated motion are v = u + at, s = ut + ½at² and v² − u² = 2as. 'u = 1/(at²)' is not one of them.","e":"v = u + at is the first.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1337","q":"What is the SI unit of energy?","o":["Newton","Joule","Mole","Ampere"],"a":1,"x":"The SI unit of energy is the joule (J), the same as for work.","e":"1 kilowatt-hour (the electricity 'unit') = 3.6 × 10⁶ J.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q2699","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options : Assertion (A): Heavier objects falls slowly than lighter objects. Reason (R) : The force of gravity is more for heavier objects.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":3,"x":"Without air resistance all objects fall at the same rate (g = 9.8 m/s²), so the assertion is false. The force of gravity is indeed greater on a heavier object, so the reason is true, but acceleration is the same.","e":"Galileo: a feather and a stone fall together in a vacuum.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2709","q":"The time rate of change of displacement of a body is called __________.","o":["acceleration","velocity","force","friction"],"a":1,"x":"The time rate of change of displacement is velocity; the rate of change of velocity is acceleration.","e":"Velocity = displacement ÷ time.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2744","q":"In the question given below, there are two statements marked as Assertion (A) and Reason (R). Mark your answer as per the codes in options : Assertion (A): We slip while dancing on a shiny floor. Reason (R) : Friction is less on a shiny surface.","o":["Both A and R are true and R is the correct explanation of A.","Both A and R are true but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"a":0,"x":"We slip on a shiny floor because a smooth surface gives less friction; the assertion and reason are both true, and the reason explains the assertion.","e":"Friction depends on surface roughness.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2754","q":"Which among the following instruments is used in aircrafts for measuring altitudes?","o":["Altimeter","Ammeter","Anemometer","Barometer"],"a":0,"x":"An altimeter measures altitude in aircraft. An ammeter measures current, an anemometer wind speed and a barometer air pressure.","e":"","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q1012","q":"In scientific research, which system of units is primarily used?","o":["US standard system","CGS system","Customary system","SI system"],"a":3,"x":"The SI (International System of Units, 1960) is used worldwide in science: metre, kilogram, second, ampere, kelvin, mole and candela.","e":"SI has 7 base units.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1425","q":"Who among the following gave the three laws of planetary motion?","o":["Newton","Rutherford","Kepler","Faraday"],"a":2,"x":"Johannes Kepler gave the three laws of planetary motion (1609–1619): elliptical orbits, equal areas in equal times, and T² ∝ r³.","e":"Newton later explained them with his law of gravitation.","src":["TGT 25 Jun 2023 S2"]}]},{"id":"heat","n":"Heat, Sound and Thermodynamics","qs":[{"id":"q1750","q":"Which of the following statement regarding sound is correct? I. Frequency is inversely proportional to time period. II. Speed of sound in water > speed of sound in oxygen. III. The repeated reflection that results in persistence of sound is called echo.","o":["I and II","II and III","I and III","I, II and III"],"a":0,"x":"Frequency = 1 / time period, and sound travels faster in water (about 1,480 m/s) than in oxygen (about 316 m/s). Persistence of sound from repeated reflections is reverberation, not echo, so only I and II are right.","e":"Echo = one clear reflection; reverberation = many overlapping ones.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1793","q":"Which of the following statement regarding sound is NOT correct? I. The audible range of hearing for average human beings is 30Hz-30kHz. II. Outer ear is called pinna. III. Ultrasounds can be used to detect cracks and flows in metal blocks. IV. Frequencies higher than 15kHz are called ultrasound.","o":["I, II and IV","II and III","I and IV","Only III"],"a":2,"x":"Human hearing is about 20 Hz–20 kHz (not 30–30 kHz), and ultrasound is above 20 kHz (not 15 kHz), so I and IV are wrong. The pinna is the outer ear, and ultrasound does detect flaws in metal.","e":"Infrasound < 20 Hz < audible < 20 kHz < ultrasound.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1946","q":"Which of the following pair is/are correct? I. Large amplitude = Loud sound II. Higher frequency = Higher pitch","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Larger amplitude gives a louder sound, and higher frequency gives a higher pitch, so both pairs are correct.","e":"Amplitude → loudness; frequency → pitch.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2528","q":"What kind of waves are sound waves?","o":["Longitudinal waves","Transverse waves","Surface waves","Electromagnetic waves"],"a":0,"x":"Sound waves are longitudinal: air particles vibrate back and forth along the direction the wave travels, forming compressions and rarefactions.","e":"Light waves are transverse.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2711","q":"As per the _________ law of Thermodynamics, heat given to a substance is equal to sum of change in internal energy and work done.","o":["Zeroth","First","Second","Third"],"a":1,"x":"The First Law of Thermodynamics: heat supplied = change in internal energy + work done (Q = ΔU + W), a form of conservation of energy.","e":"","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q0898","q":"Which law of thermodynamics states that heat cannot spontaneously flow from a colder object to a hotter object without external intervention?","o":["First","Second","Third","Zeroth"],"a":1,"x":"The second law of thermodynamics (Clausius form) says heat cannot flow on its own from a colder body to a hotter one; a refrigerator needs work to do it.","e":"First law: energy is conserved. Second law: entropy rises.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0948","q":"Which of the following is an example of an open system?","o":["A thermos flask with a tight lid","Hot coffee kept in a cup","A closed bottle of soda","A sealed pressure cooker"],"a":1,"x":"An open system exchanges both matter and energy with its surroundings: hot coffee in an open cup loses heat and water vapour. A closed system (sealed bottle, pressure cooker) exchanges only energy; an isolated one (thermos) exchanges neither.","e":"Open = matter + energy; closed = energy only; isolated = nothing.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1004","q":"What is the key component inside a decibel meter that helps detect sound pressure?","o":["Magnetic coil","Microphone","LED sensor","Optical fiber"],"a":1,"x":"A decibel (sound level) meter uses a microphone to pick up sound pressure changes and turn them into an electrical signal.","e":"The decibel scale is logarithmic: +10 dB means 10 times the sound intensity.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1452","q":"What is the SI unit of thermodynamic temperature as per the International System of Units?","o":["Kelvin","Thermos","Fahrenheit","Celsius"],"a":0,"x":"The kelvin (K) is the SI unit of thermodynamic temperature; 0 K is absolute zero (−273.15°C).","e":"K = °C + 273.15.","src":["TGT 25 Jun 2023 S3"]},{"id":"q0822","q":"Which of the following law states that ‘two systems in thermal equilibrium with a third system separately are in thermal equilibrium with each other'?","o":["The first law of thermodynamics","Fourier's law","Joule's First law","The zeroth law of thermodynamics"],"a":3,"x":"The zeroth law of thermodynamics: if two systems are each in thermal equilibrium with a third, they are in equilibrium with each other. This is what makes a thermometer work.","e":"First law: energy conservation (ΔU = Q − W).","src":["PGT 26 Sep 2025"]}]},{"id":"light","n":"Light and Optics","qs":[{"id":"q1620","q":"Which of the following is NOT an example of refraction of light?","o":["Moonlight","bent pencil in glass of water","Rainbow","appearing of raised coin in a trough filled with water"],"a":0,"x":"Moonlight is sunlight reflected off the Moon, so it is reflection, not refraction. A bent pencil in water, a rainbow and a coin appearing raised are all refraction.","e":"A rainbow uses refraction, dispersion and internal reflection.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0493","q":"Which among the following defects is also known as far-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":2,"x":"Hypermetropia (far-sightedness): far objects are clear but near ones blur. It is corrected with a convex lens.","e":"Myopia (near-sightedness) uses a concave lens; presbyopia is age-related loss of near focus.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0614","q":"Which among the following defects is also known as near-sightedness?","o":["Myopia","Cataract","Hypermetropia","Presbyopia"],"a":0,"x":"Myopia (near-sightedness): near objects are clear, distant ones blur because the image forms before the retina. A concave lens corrects it.","e":"Hypermetropia (far-sightedness) is corrected by a convex lens.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q1833","q":"Which of the following is correct pair of position of the object – position of the image – size of image in a concave mirror? I. At infinity – at focus – highly diminished II. At C – At C – enlarged III. At focus – At infinity – highly enlarged","o":["I and II","II and III","I and III","Only III"],"a":2,"x":"In a concave mirror, an object at infinity forms a highly diminished image at the focus; an object at the focus forms a highly enlarged image at infinity; an object at C forms a same-size image at C (not enlarged). So I and III are right.","e":"At C → same size at C.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1987","q":"Which of the following pair is/are correct? I. Convex mirror – object at infinity – image virtual and erect II. Concave mirror – object at C – same sized image","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"A convex mirror always forms a virtual, erect, smaller image, including for an object at infinity; a concave mirror forms a same-size image at C when the object is at C. Both pairs are correct.","e":"Convex mirrors are used as rear-view mirrors.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2029","q":"Which of the following is used by dentist?","o":["Convex mirror","Concave mirror","Convex lens","Concave lens"],"a":1,"x":"Dentists use a concave mirror: held close to a tooth, it gives an enlarged, erect image.","e":"Concave: dentists, shaving mirrors, torches; convex: rear-view mirrors.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2032","q":"Which of the following pair is/are correct? I. Myopia – corrected by concave lens II. Hypermetropia – corrected by convex lens","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Myopia (short sight) is corrected with a concave lens, and hypermetropia (long sight) with a convex lens.","e":"Myopia → concave; hypermetropia → convex.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2110","q":"Which of the following pair of phenomenon – effect is correct? I. Atmospheric refraction – Twinkling of stars II. Atmospheric refraction – Tyndall effect III. Scattering of light – Colour of clear sky being blue IV. Scattering of light – Advance sunrise and delay sunset","o":["I and IV","II and III","I and III","III तथा IV"],"a":2,"x":"Atmospheric refraction makes stars twinkle and causes early sunrise and delayed sunset; scattering makes the sky blue and causes the Tyndall effect. So I and III are correct.","e":"Twinkling = refraction; blue sky = scattering.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q1163","q":"What is the SI unit for measuring luminous intensity in a given direction?","o":["Candela","Roentgen","Curie","Weber"],"a":0,"x":"The candela is the SI unit of luminous intensity; it is one of the seven SI base units.","e":"Lumen = luminous flux; lux = illuminance.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1275","q":"Unlike sound waves, electromagnetic waves can travel through ____________.","o":["Water only","Air only","Solids only","Vacuum"],"a":3,"x":"Electromagnetic waves (light, radio, X-rays) need no medium and travel through a vacuum at 3 × 10⁸ m/s; sound needs a medium.","e":"That is why we see the Sun but cannot hear it.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1365","q":"Malus' Law is related to which of the following subjects?","o":["Inertia","Surface tension","Gravitation","Light"],"a":3,"x":"Malus' law is about polarised light: the intensity passing through an analyser is I = I₀ cos²θ, where θ is the angle between the polariser and analyser.","e":"Polarised sunglasses cut glare using this principle.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1399","q":"How many internal reflections do light rays undergo, inside a raindrop, to form a secondary rainbow?","o":["One","Four","Three","Two"],"a":3,"x":"A secondary rainbow forms after two internal reflections inside raindrops (a primary rainbow after one), so its colours are reversed and fainter.","e":"The primary rainbow has red on the outside; the secondary has red on the inside.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1554","q":"Transverse nature of light causes:","o":["convergent nature of light","reflection of light","polarisation of light","divergent nature of light"],"a":2,"x":"Only transverse waves can be polarised, so polarisation proves that light is a transverse wave.","e":"Sound in air is longitudinal and cannot be polarised.","src":["TGT 31 Aug 2025 S1"]}]},{"id":"electricity","n":"Electricity and Magnetism","qs":[{"id":"q0224","q":"When the discharge takes place between opposite charges accumulated in different clouds, the type of lightning produced is:","o":["cloud to air lightning","cloud to ground lightning","cloud to cloud lightning","intra cloud lightning"],"a":2,"x":"When charges jump between oppositely charged regions of two different clouds, the result is cloud-to-cloud (inter-cloud) lightning.","e":"Inside a single cloud it is intra-cloud lightning; the most dangerous kind is cloud-to-ground.","src":["ASO 20 Aug 2025 S1"]},{"id":"q1605","q":"Which of the following is NOT a basic feature of magnets?","o":["Directive property","Magnet exists as a monopole","Attractive property","Like poles repel and unlike poles attract"],"a":1,"x":"A magnet always has two poles (north and south); a magnetic monopole has never been found. Cut a magnet in half and each piece has both poles.","e":"Magnets attract iron, point north–south when free, and like poles repel.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0533","q":"Which among the following laws states that the current passing through a conductor between two points is directly proportional to the potential difference across the two points provided the physical state and temperature etc. of the conductor does not change?","o":["Ohm's Law","Avogadro's Law","Coulomb’s Law","Pascal’s Law"],"a":0,"x":"Ohm's law: at constant temperature, the current through a conductor is directly proportional to the potential difference across it (V = IR).","e":"A 12 V battery across a 4 Ω resistor drives 3 A.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0574","q":"Which among the following laws states that induced electromotive force with different polarities induces a current whose magnetic field opposes the change in magnetic flux through the loop in order to ensure that original flux is maintained through the loop when current flows in it?","o":["Lenz's Law","Ohm's Law","Snell's Law","Boyle's Law"],"a":0,"x":"Lenz's law: the induced current flows in a direction whose magnetic field opposes the change in flux that produced it. This follows from conservation of energy.","e":"It explains the minus sign in Faraday's law.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0651","q":"An electric generator is a device that converts _______________ energy into electrical energy.","o":["sound","chemical","nuclear","mechanical"],"a":3,"x":"An electric generator (dynamo) converts mechanical energy into electrical energy through electromagnetic induction.","e":"An electric motor does the reverse.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q1914","q":"Which of the following is not a unit of Electric Power?","o":["Watts","Joule per second","Volt per metre","Calorie per second"],"a":2,"x":"Power is energy per time: watt, joule per second and calorie per second are all power units. Volt per metre is the unit of electric field, not power.","e":"1 W = 1 J/s; 1 calorie ≈ 4.186 J.","src":["Junior Clerk 13 Nov 2021 S3","Scientific Assistant (Ballistics) 11 Sep 2021 S3"]},{"id":"q2756","q":"The SI unit of Resistance is ________.","o":["Watt","Ohm","Joule","Pascal"],"a":1,"x":"The SI unit of resistance is the ohm (Ω).","e":"V = IR.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q0912","q":"Electric and magnetic fields are regarded as:","o":["Scalar quantities because they have only magnitude","Non-physical entities without measurable effects","Independent phenomena with no relation","Vector quantities because they have both magnitude and direction"],"a":3,"x":"Electric and magnetic fields are vector quantities: they have both magnitude and direction at every point.","e":"Other vectors: force, velocity. Scalars: mass, temperature, energy.","src":["PRT 17 Feb 2026 S3"]},{"id":"q1096","q":"Where is the magnetic field strongest on a magnet?","o":["At the poles","Only at one end","Equally everywhere","At the centre"],"a":0,"x":"A magnet's field is strongest at its poles, where field lines are closest together; that is why iron filings cluster at the ends.","e":"Like poles repel, unlike poles attract.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1122","q":"What is the force between two small charged particles of 4 × 10⁻⁶ C and 6 × 10⁻⁶ C placed 20 cm apart in air?","o":["5.4 × 10⁻² N","5.4 × 10⁻⁴ N","5.4 N","5400 N"],"a":2,"x":"By Coulomb's law F = k·q₁q₂/r² = 9×10⁹ × (4×10⁻⁶ × 6×10⁻⁶) / (0.2)² = 0.216/0.04 = 5.4 N.","e":"Double the distance → force drops to a quarter.","src":["PRT 26 Mar 2026 S1"]}]}]});
